#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 700

library(shiny)


shinyApp(
  ui = fluidPage(
    selectInput(
      "type",
      label = "Choose your criminal",
      choices = c(
        "Choose here" = "",
        "Klara Cache",
        "Kommissar RegEx",
        "Sava Sniffer",
        "Vera Vector",
        "Byte Biter"
      ), 
      selected = ""

    ),

    textOutput("text_output"),
    uiOutput("image_output")
  ),

  server = function(input, output) {

    output$image_output &lt;- renderUI({
      if (input$type == "") return(NULL)
      if (input$type == "Byte Biter") {
        tags$img(
          src = "../dog_portraits/06_mugshot.png",
          alt = "Byte Biter",
          width = "500px"
        )
      } else {
        tags$img(
          src = "../dog_portraits/07_escape.png",
          alt = "Wrong suspect",
          width = "500px"
        )
      }
    })

    output$text_output &lt;- renderText({
      if (input$type == "") return("")
      if (input$type == "Byte Biter") {
        "You are a true detective! You found the criminal that killed the session!"
      } else {
        "You made the wrong choice. Now Byte Biter gained more attitude and is on the loose!!"
      }
    })
  }
)

